entradas.sintaxe:
SELECT colunas
FROM tabela
WHERE condicao;

SELECT coluna, COUNT(*)
FROM tabela
GROUP BY coluna;

entradas.exemplo:
SELECT categoria, COUNT(*) AS produtos
FROM produtos
GROUP BY categoria;

SELECT COUNT(*) FILTER (WHERE status = 'pago') AS pagos,
       COUNT(*) FILTER (WHERE status = 'cancelado') AS cancelados
FROM pedidos;

entradas.sintaxe:
SELECT a.coluna, b.coluna
FROM tabela_a a
JOIN tabela_b b ON b.chave = a.chave;

SELECT a.coluna, b.coluna
FROM tabela_a a
LEFT JOIN tabela_b b ON b.chave = a.chave;

SELECT a.*
FROM tabela_a a
WHERE NOT EXISTS (
  SELECT 1 FROM tabela_b b WHERE b.chave = a.chave
);

entradas.exemplo:
SELECT c.nome
FROM clientes c
WHERE NOT EXISTS (
  SELECT 1 FROM pedidos p WHERE p.cliente_id = c.cliente_id
);

entradas.sintaxe:
SELECT colunas FROM tabela_a
UNION ALL
SELECT colunas FROM tabela_b;

entradas.exemplo:
SELECT nome, 'cliente' AS tipo FROM clientes WHERE uf = 'PE'
UNION ALL
SELECT nome, 'produto' FROM produtos WHERE categoria = 'Livros';

SELECT nome
FROM clientes
WHERE email IS NULL;

SELECT strftime(criado_em, '%d/%m/%Y %H:%M') AS quando
FROM pedidos
LIMIT 5;

SELECT nome, preco
FROM produtos
WHERE preco > (SELECT AVG(preco) FROM produtos);

SELECT AVG(qtd) AS media_itens
FROM (
  SELECT pedido_id, COUNT(*) AS qtd
  FROM itens_pedido
  GROUP BY pedido_id
) AS por_pedido;

