entradas.exemplo:
SELECT nome, categoria, preco,
       RANK() OVER (PARTITION BY categoria ORDER BY preco DESC) AS posicao
FROM produtos;

entradas.sintaxe:
SELECT ...
FROM tabela
QUALIFY ROW_NUMBER() OVER (...) = 1;

entradas.exemplo:
SELECT categoria, nome, preco
FROM produtos
QUALIFY ROW_NUMBER() OVER (PARTITION BY categoria ORDER BY preco DESC) = 1;
